import{_ as t,o,c as r,a0 as i}from"./chunks/framework.BYCjvD8D.js";const p=JSON.parse('{"title":"Original MarI/O video and Lua implementation","description":"","frontmatter":{},"headers":[],"relativePath":"original-mar-io.md","filePath":"original-mar-io.md"}'),a={name:"original-mar-io.md"};function n(s,e,l,c,d,u){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="original-mari-o-video-and-lua-implementation" tabindex="-1">Original MarI/O video and Lua implementation <a class="header-anchor" href="#original-mari-o-video-and-lua-implementation" aria-label="Permalink to &quot;Original MarI/O video and Lua implementation&quot;">​</a></h1><h2 id="what-the-source-actually-shows" tabindex="-1">What the source actually shows <a class="header-anchor" href="#what-the-source-actually-shows" aria-label="Permalink to &quot;What the source actually shows&quot;">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=qv6UVOQ0F44" target="_blank" rel="noreferrer">Video: MarI/O — Machine Learning for Video Games</a>, SethBling, published 13 June 2015. <strong>Game:</strong> Super Mario World.</li><li><a href="https://gist.github.com/SethBling" target="_blank" rel="noreferrer">SethBling&#39;s published gist listing</a>. An accessible Lua copy contains a header identifying the original author, the <strong>BizHawk</strong> emulator, an approximately <strong>13 × 13 tile neighbourhood</strong>, and controller actions.</li><li><a href="https://nn.cs.utexas.edu/downloads/papers/stanley.ec02.pdf" target="_blank" rel="noreferrer">NeuroEvolution of Augmenting Topologies paper</a>, Stanley &amp; Miikkulainen (2002).</li></ul><p><strong>Source restriction:</strong> the widely circulated Lua script expressly asks not to be redistributed. This repository does not copy or translate its source code; it independently implements mathematical concepts described in the academic paper and uses original game data/art.</p><h2 id="comparison-with-the-reference-github-project" tabindex="-1">Comparison with the reference GitHub project <a class="header-anchor" href="#comparison-with-the-reference-github-project" aria-label="Permalink to &quot;Comparison with the reference GitHub project&quot;">​</a></h2><p>The separately supplied <a href="https://github.com/ifthenelse/Super-Mario-Bros-AI" target="_blank" rel="noreferrer">ifthenelse/Super-Mario-Bros-AI</a> is <strong>not the same software</strong>:</p><ul><li>It targets <strong>Super Mario Bros</strong> on the Nintendo Entertainment System, not the Super Nintendo game in SethBling&#39;s video.</li><li>It runs in Python using <code>stable-retro</code> and <code>neat-python</code>.</li><li>Its observations include positions, velocity, enemy slots, a terrain grid and contextual features derived from emulator memory.</li><li>It requires a locally supplied game ROM and is not browser-only.</li><li>Its repository is not currently licensed for reuse in our source; we cite it as a reference rather than copying its code.</li></ul><h2 id="our-clean-room-reconstruction" tabindex="-1">Our clean-room reconstruction <a class="header-anchor" href="#our-clean-room-reconstruction" aria-label="Permalink to &quot;Our clean-room reconstruction&quot;">​</a></h2><p>The original experiment provides an educational design target, not a benchmark claim. Our version starts from a new deterministic platformer:</p><ol><li>A moving robot observes a local terrain/enemy grid.</li><li>A feed-forward neural network outputs left/right/jump decisions.</li><li>The environment runs a complete episode.</li><li>Fitness is based primarily on progress and completion.</li><li>The evolutionary population undergoes selection, fitness sharing, crossover, weight mutation and structural mutation.</li><li>The best genome is replayed and its network shown graphically.</li></ol><p><strong>Differences:</strong> custom physics and hazards, three action outputs, simplified compatibility/reproduction, no emulator memory-reading and no copyrighted game content. The initial version is not validated as a numerically identical NEAT implementation.</p><h2 id="important-terminology" tabindex="-1">Important terminology <a class="header-anchor" href="#important-terminology" aria-label="Permalink to &quot;Important terminology&quot;">​</a></h2><p><strong>NeuroEvolution of Augmenting Topologies (NEAT)</strong> is the method applied to game policies. It is distinct from a <strong>Mobile Ad Hoc Network (MANET)</strong> routing algorithm, despite the coincidental connection to the author&#39;s 2004 networking dissertation.</p>',13)])])}const m=t(a,[["render",n]]);export{p as __pageData,m as default};
